#!/usr/bin/env python3
import sys

MOD = 1000000007  # type: int


def solve(N: int, S: str):
    abc = "abcdefghijklmnopqrstuvwxyz"
    ans = 2**N % MOD
    n = N
    pre = 1
    for c in abc:
        count = S.count(c)
        kaburi = ((2 ** count)-1-count)
        ans -= pre * kaburi * (2 ** (n - count))
        pre *= (1 + count) % MOD
        n -= count
        ans = ans % MOD
    print(int(ans-1))
    return


# Generated by 1.1.3 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    S = next(tokens)  # type: str
    solve(N, S)


if __name__ == '__main__':
    main()
